import React from 'react';
import {AbsoluteFill, Img, staticFile, useCurrentFrame} from 'remotion';
import {C, F, clamp01, easeInCubic, easeInOutCubic, easeOutCubic, easeOutExpo, prand, win} from './theme';

// ---------------- narration (word-timed VO) ----------------
// Generated by make_narration.py — absolute film frames per spoken word.
import NARR from './narration.json';
type NarrWord = {w: string; f: number; d: number};
type NarrLine = {start: number; text: string; words: NarrWord[]; zoom_words: string[]};
const NARR_MAP = NARR as unknown as Record<string, NarrLine>;
const normw = (s: string) => s.toLowerCase().replace(/[^a-z]/g, '');

/** Scale multiplier that punches in on the frame the narrator says the named thing. */
export const narrZoom = (frame: number, seg?: string, amount = 0.085): number => {
  if (!seg) return 1;
  const line = NARR_MAP[seg];
  if (!line) return 1;
  let s = 1;
  for (const wd of line.words) {
    if (line.zoom_words.some((z) => normw(wd.w) === z)) {
      const t = (frame - (wd.f - 4)) / 24;
      if (t > 0 && t < 1) s += amount * Math.pow(Math.sin(Math.PI * t), 0.85);
    }
  }
  return s;
};

/** Karaoke captions — active word highlighted; 60-80% of feed views start muted. */
export const CaptionTrack: React.FC = () => {
  const f = useCurrentFrame();
  let active: NarrLine | null = null;
  for (const key of Object.keys(NARR_MAP)) {
    const line = NARR_MAP[key];
    const last = line.words[line.words.length - 1];
    if (last && f >= line.start - 2 && f <= last.f + last.d + 18) active = line;
  }
  if (!active) return null;
  const words = active.words.filter((w) => w.f <= f + 1);
  if (!words.length) return null;
  let activeIdx = 0;
  words.forEach((w, i) => { if (f >= w.f) activeIdx = i; });
  return (
    <AbsoluteFill style={{justifyContent: 'flex-end', alignItems: 'center', paddingBottom: 78}}>
      <div style={{display: 'flex', gap: 14, maxWidth: 1520, flexWrap: 'wrap', justifyContent: 'center'}}>
        {words.map((w, i) => {
          const on = i === activeIdx;
          return (
            <span key={i} style={{
              fontFamily: F.sans, fontWeight: 700, fontSize: on ? 34 : 29,
              color: on ? C.amber : C.white, opacity: on ? 1 : 0.82,
              textShadow: '0 2px 12px rgba(0,0,0,0.9), 0 0 26px rgba(0,0,0,0.7)',
              transform: on ? 'scale(1.07)' : 'scale(1)',
            }}>{w.w}</span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

