/* ============================= PHOTO LAYERS ============================= */
export const KenBurns: React.FC<{
  src: string;
  from: number;
  dur: number;
  zoomFrom?: number;
  zoomTo?: number;
  panX?: number; // % shift over the shot
  panY?: number;
  brightness?: number;
  sepia?: number;
  narrSeg?: string; // narration key -> word-driven zoom bumps
}> = ({src, from, dur, zoomFrom = 1.06, zoomTo = 1.16, panX = 0, panY = 0, brightness = 1, sepia = 0, narrSeg}) => {
  const frame = useCurrentFrame();
  const p = easeInOutCubic(clamp01((frame - from) / dur));
  const nz = narrZoom(frame, narrSeg);
  const scale = (zoomFrom + (zoomTo - zoomFrom) * p) * nz;
  const tx = panX * p;
  const ty = panY * p;
  return (
    <AbsoluteFill style={{overflow: 'hidden'}}>
      <Img
        src={staticFile(src)}
        style={{
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          transform: `scale(${scale}) translate(${tx}%, ${ty}%)`,
          filter: `brightness(${brightness}) saturate(0.82) contrast(1.08) sepia(${sepia})`,
        }}
      />
    </AbsoluteFill>
  );
};

