/* ============================= TYPE ============================= */
export const BlurWords: React.FC<{
  words: string[];
  start: number;
  stagger?: number;
  dur?: number;
  style?: React.CSSProperties;
  color?: string;
  accentIndex?: number;
  accentColor?: string;
  rise?: number;
}> = ({words, start, stagger = 4, dur = 11, style, color = C.white, accentIndex = -1, accentColor = C.amber, rise = 22}) => {
  const frame = useCurrentFrame();
  return (
    <div style={{display: 'flex', flexWrap: 'wrap', gap: '0 0.3em', ...style}}>
      {words.map((w, i) => {
        const p = win(frame, start + i * stagger, dur);
        const e = easeOutExpo(p);
        return (
          <span
            key={i}
            style={{
              display: 'inline-block',
              opacity: e,
              filter: `blur(${(1 - e) * 13}px)`,
              transform: `translateY(${(1 - e) * rise}px)`,
              color: i === accentIndex ? accentColor : color,
              textShadow: '0 2px 24px rgba(0,0,0,0.55)',
            }}
          >
            {w}
          </span>
        );
      })}
    </div>
  );
};

export const Typewriter: React.FC<{
  text: string;
  start: number;
  speed?: number; // chars per frame
  style?: React.CSSProperties;
  cursor?: boolean;
}> = ({text, start, speed = 0.9, style, cursor = true}) => {
  const frame = useCurrentFrame();
  const n = Math.floor(Math.max(0, frame - start) * speed);
  const shown = text.slice(0, n);
  const blink = Math.floor(frame / 12) % 2 === 0;
  return (
    <div style={{whiteSpace: 'pre-wrap', ...style}}>
      {shown}
      {cursor && n < text.length && <span style={{opacity: blink ? 1 : 0.2}}>|</span>}
    </div>
  );
};

/* ============================= HUD / STAMPS ============================= */
export const Slug: React.FC<{
  scene: string;
  time: string;
  place: string;
  start: number;
  accent?: string;
}> = ({scene, time, place, start, accent = C.amber}) => {
  const frame = useCurrentFrame();
  const p = win(frame, start, 12);
  const e = easeOutExpo(p);
  return (
    <div
      style={{
        position: 'absolute',
        top: 112,
        left: 72,
        display: 'flex',
        alignItems: 'center',
        gap: 16,
        fontFamily: F.mono,
        opacity: e,
        transform: `translateX(${(1 - e) * -26}px)`,
      }}
    >
      <div style={{width: 38, height: 3, background: accent}} />
      <div style={{color: accent, fontSize: 21, letterSpacing: '0.22em', fontWeight: 600}}>{scene}</div>
      <div style={{color: C.paperDim, fontSize: 21, letterSpacing: '0.18em'}}>{time}</div>
      <div style={{color: C.paperDim, fontSize: 21, letterSpacing: '0.18em'}}>— {place}</div>
    </div>
  );
};

export const Clock: React.FC<{start: number; baseSec: number}> = ({start, baseSec}) => {
  const frame = useCurrentFrame();
  const t = baseSec + Math.max(0, frame - start) / 30;
  const hh = Math.floor(t / 3600) % 24;
  const mm = Math.floor(t / 60) % 60;
  const ss = Math.floor(t) % 60;
  const ff = Math.floor(frame % 30);
  const pad = (x: number) => String(x).padStart(2, '0');
  return (
    <div
      style={{
        position: 'absolute',
        right: 72,
        bottom: 112,
        fontFamily: F.mono,
        fontSize: 19,
        color: C.hudDim,
        letterSpacing: '0.14em',
      }}
    >
      {pad(hh)}:{pad(mm)}:{pad(ss)}:{pad(ff)}
    </div>
  );
};

export const Stamp: React.FC<{
  text: string;
  start: number;
  x: number;
  y: number;
  rot?: number;
  color?: string;
  size?: number;
}> = ({text, start, x, y, rot = -8, color = C.warnGlow, size = 40}) => {
  const frame = useCurrentFrame();
  const p = win(frame, start, 9);
  const e = easeOutExpo(p);
  return (
    <div
      style={{
        position: 'absolute',
        left: x,
        top: y,
        transform: `rotate(${rot}deg) scale(${1.7 - 0.7 * e})`,
        opacity: e * 0.92,
        fontFamily: F.type,
        fontSize: size,
        color,
        border: `4px solid ${color}`,
        borderRadius: 8,
        padding: '6px 20px',
        letterSpacing: '0.12em',
        mixBlendMode: 'screen',
      }}
    >
      {text}
    </div>
  );
};

export const RedactedBar: React.FC<{
  w: number | string;
  start: number;
  retract?: boolean;
  style?: React.CSSProperties;
}> = ({w, start, retract = false, style}) => {
  const frame = useCurrentFrame();
  const p = win(frame, start, 10);
  const e = easeOutCubic(p);
  return (
    <div
      style={{
        display: 'inline-block',
        height: '0.82em',
        width: typeof w === 'number' ? `${w * (retract ? 1 - e : 1)}px` : w,
        background: '#0A0A0A',
        verticalAlign: 'middle',
        margin: '0 0.35em',
        opacity: retract ? 1 - e * 0.9 : e,
        transform: `translateY(${(1 - e) * 6}px)`,
        ...style,
      }}
    />
  );
};

/* ============================= FX ============================= */
export const AlarmPulse: React.FC<{from: number; dur: number}> = ({from, dur}) => {
  const frame = useCurrentFrame();
  if (frame < from || frame > from + dur) return null;
  const t = (frame - from) / 12;
  const pulse = 0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.5);
  return (
    <AbsoluteFill
      style={{
        pointerEvents: 'none',
        background: `radial-gradient(ellipse at center, rgba(255,60,40,${0.05 + 0.11 * pulse}) 0%, rgba(255,60,40,0) 70%)`,
        mixBlendMode: 'screen',
      }}
    />
  );
};

export const Glitch: React.FC<{from: number; dur: number; strength?: number}> = ({from, dur, strength = 1}) => {
  const frame = useCurrentFrame();
  if (frame < from || frame > from + dur) return null;
  const local = frame - from;
  const active = prand(frame) > 0.55 ? 1 : 0.15;
  const shift = (prand(frame * 3.7) - 0.5) * 22 * strength * active;
  return (
    <>
      <AbsoluteFill
        style={{
          pointerEvents: 'none',
          mixBlendMode: 'screen',
          opacity: 0.28 * active * strength,
          background: `linear-gradient(90deg, rgba(255,0,60,0.35) 0%, rgba(255,0,60,0) 24%, rgba(0,255,255,0.35) 52%, rgba(0,255,255,0) 78%, rgba(255,0,60,0.3) 100%)`,
          transform: `translateX(${shift}px)`,
        }}
      />
      {[0, 1, 2].map((i) => {
        const top = ((prand(local * 7.3 + i * 13.7) * 100) | 0) + '%';
        const h = 3 + prand(local * 3.1 + i * 7.7) * 22;
        return (
          <div
            key={i}
            style={{
              position: 'absolute',
              left: 0,
              right: 0,
              top,
              height: h,
              background: i % 2 ? 'rgba(255,255,255,0.20)' : 'rgba(120,200,255,0.18)',
              transform: `translateX(${(prand(local * 5.1 + i * 3.3) - 0.5) * 60 * strength}px)`,
              mixBlendMode: 'screen',
              opacity: active,
              pointerEvents: 'none',
            }}
          />
        );
      })}
    </>
  );
};

export const RadarSweep: React.FC<{start: number; size?: number}> = ({start, size = 300}) => {
  const frame = useCurrentFrame();
  const p = win(frame, start, 12);
  const e = easeOutCubic(p);
  const angle = ((frame - start) * 3.2) % 360;
  return (
    <div
      style={{
        position: 'absolute',
        width: size,
        height: size,
        borderRadius: '50%',
        opacity: e,
        transform: `scale(${0.85 + 0.15 * e})`,
      }}
    >
      <svg width={size} height={size} viewBox="0 0 200 200">
        {[38, 66, 94].map((r) => (
          <circle key={r} cx="100" cy="100" r={r} fill="none" stroke={C.hudDim} strokeWidth="1.2" />
        ))}
        <line x1="100" y1="6" x2="100" y2="194" stroke={C.hudDim} strokeWidth="1" />
        <line x1="6" y1="100" x2="194" y2="100" stroke={C.hudDim} strokeWidth="1" />
        <g transform={`rotate(${angle} 100 100)`}>
          <path d="M100 100 L100 8 A92 92 0 0 1 165 35 Z" fill={C.phosphor} opacity="0.16" />
          <line x1="100" y1="100" x2="100" y2="8" stroke={C.phosphor} strokeWidth="1.6" opacity="0.7" />
        </g>
        {[0, 1, 2].map((i) => {
          const rr = ((frame - start - i * 22) % 66 + 66) % 66;
          return (
            <circle
              key={i}
              cx="118"
              cy="72"
              r={4 + rr * 0.7}
              fill="none"
              stroke={C.phosphor}
              strokeWidth="1.4"
              opacity={0.65 * (1 - rr / 66) * e}
            />
          );
        })}
        <circle cx="118" cy="72" r="4" fill={C.phosphor} opacity="0.95" />
      </svg>
    </div>
  );
};

export const Waveform: React.FC<{start: number; w?: number; h?: number}> = ({start, w = 320, h = 64}) => {
  const frame = useCurrentFrame();
  const bars = 36;
  return (
    <div style={{display: 'flex', alignItems: 'center', gap: 3, height: h, opacity: win(frame, start, 10)}}>
      {Array.from({length: bars}).map((_, i) => {
        const t = frame - start;
        const v =
          0.25 +
          0.75 *
            Math.abs(
              Math.sin(t * 0.16 + i * 0.55) * 0.6 +
                Math.sin(t * 0.07 + i * 1.7) * 0.4
            ) *
            (0.55 + 0.45 * prand(i * 3.7));
        return (
          <div
            key={i}
            style={{
              width: (w - bars * 3) / bars,
              height: h * v,
              background: C.phosphor,
              opacity: 0.35 + 0.5 * v,
              borderRadius: 2,
            }}
          />
        );
      })}
    </div>
  );
};

export const FreqReadout: React.FC<{start: number}> = ({start}) => {
  const frame = useCurrentFrame();
  const p = win(frame, start, 12);
  const jitter = prand(Math.floor(frame / 2)) * 0.004;
  return (
    <div
      style={{
        fontFamily: F.mono,
        color: C.phosphor,
        fontSize: 66,
        fontWeight: 700,
        letterSpacing: '0.02em',
        opacity: easeOutCubic(p),
        textShadow: `0 0 22px ${C.hudDim}`,
      }}
    >
      1.7{(jitter * 10).toFixed(2)} <span style={{fontSize: 30}}>GHz</span>
    </div>
  );
};

export const BeamGlow: React.FC<{start: number}> = ({start}) => {
  const frame = useCurrentFrame();
  const p = win(frame, start, 22);
  const breathe = 0.85 + 0.15 * Math.sin((frame - start) / 11);
  return (
    <AbsoluteFill
      style={{
        pointerEvents: 'none',
        opacity: p * breathe,
        mixBlendMode: 'screen',
        background:
          'radial-gradient(ellipse 24% 75% at 50% 38%, rgba(127,217,255,0.34) 0%, rgba(127,217,255,0.10) 40%, rgba(127,217,255,0) 72%)',
      }}
    />
  );
};

/* Scene wrapper: fast crossfade between segments */
export const Seg: React.FC<{from: number; dur: number; children: React.ReactNode}> = ({from, dur, children}) => {
  const frame = useCurrentFrame();
  const enter = win(frame, from, 10);
  const exit = win(frame, from + dur - 10, 10);
  if (frame < from - 1 || frame > from + dur + 8) return null;
  return (
    <AbsoluteFill
      style={{
        opacity: easeOutCubic(enter) * (1 - easeInCubic(exit)),
        transform: `scale(${1 + 0.025 * (1 - easeOutCubic(enter))})`,
      }}
    >
      {children}
    </AbsoluteFill>
  );
};
